import{_ as r,o as a,c as o,a2 as d}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"程序化交易","description":"","frontmatter":{},"headers":[],"relativePath":"features/auto-trading.md","filePath":"features/auto-trading.md","lastUpdated":null}'),e={name:"features/auto-trading.md"};function s(n,t,l,i,g,h){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="程序化交易" tabindex="-1">程序化交易 <a class="header-anchor" href="#程序化交易" aria-label="Permalink to &quot;程序化交易&quot;">​</a></h1><p>程序化交易以 <strong>模组（Module）</strong> 为核心运行单元：<strong>模组 = 策略 × 账户 × 合约</strong>，即&quot;哪个策略在哪个账户上对哪个品种进行交易&quot;。创建模组并启用后，策略便会自动接收行情、发出交易信号并下单。</p><h2 id="模组管理页" tabindex="-1">模组管理页 <a class="header-anchor" href="#模组管理页" aria-label="Permalink to &quot;模组管理页&quot;">​</a></h2><p>进入 <strong>交易自动化 → 模组管理</strong>（<code>Alt+2</code>），表格展示全部模组：</p><table tabindex="0"><thead><tr><th>列</th><th>说明</th></tr></thead><tbody><tr><td>模组名称</td><td>唯一标识</td></tr><tr><td>模组类型</td><td>投机 / 套利</td></tr><tr><td>模组用途</td><td>回测 / 模拟盘 / 实盘</td></tr><tr><td>交易策略</td><td>绑定的策略</td></tr><tr><td>平仓逻辑</td><td>FIFO 先开先平 / FILO 平今优先 / CPHT 平昨锁今（悬停显示全称）</td></tr><tr><td>交易账户 / 交易合约</td><td>绑定的账户与合约</td></tr><tr><td>模组状态</td><td>无持仓 / 多头持仓 / 空头持仓 / 对冲锁仓 / 对冲持仓 / 等待中 / 异常</td></tr><tr><td>启停状态</td><td>已启用 / 已停用</td></tr></tbody></table><p>勾选多行后，&quot;启用/停用&quot;变为<strong>批量操作</strong>。每行的&quot;操作&quot;下拉提供：</p><ul><li><strong>启用 / 停用</strong>：启停模组（快捷键之外最常用的操作）；</li><li><strong>修改</strong>：仅停用状态可修改；</li><li><strong>复制</strong>：以该模组为模板快速创建新模组；</li><li><strong>运行时状态</strong>：打开模组监控详情页（见下文）；</li><li><strong>查看日志</strong>：跳转该模组的专属日志；</li><li><strong>重置</strong>：清空模组账户与持仓（需确认）；</li><li><strong>移除</strong>：仅停用状态可删除。</li></ul><h2 id="新建模组" tabindex="-1">新建模组 <a class="header-anchor" href="#新建模组" aria-label="Permalink to &quot;新建模组&quot;">​</a></h2><p>点击 <strong>新建</strong>，弹窗分为四个页签：</p><h3 id="_1-模组信息" tabindex="-1">① 模组信息 <a class="header-anchor" href="#_1-模组信息" aria-label="Permalink to &quot;① 模组信息&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>模组名称</td><td>不超过 16 个字符，创建后不可改</td></tr><tr><td>分配金额</td><td>模组账户的初始资金（默认 10000）</td></tr><tr><td>模组类型</td><td>投机 / 套利</td></tr><tr><td>模组用途</td><td><strong>回测</strong> / <strong>模拟盘</strong> / <strong>实盘</strong></td></tr><tr><td>平仓逻辑</td><td>先开先平 / 平今优先 / 平昨锁今（平昨锁今仅实盘可选）</td></tr><tr><td>预热数据量</td><td>加载多少周的历史数据用于指标预热（回测用途强制为 0，由回放网关控制预热）</td></tr><tr><td>图表数据量</td><td>模组缓存的K线条数（默认 500，最小 100）</td></tr><tr><td>默认下单量</td><td>每次开仓的手数单位（既可作每次开仓量也可作最大开仓量，由策略实现决定）</td></tr><tr><td>超价</td><td>在限价基础上优惠 N 个价位，提高成交率（单位：价位）</td></tr></tbody></table><h3 id="_2-交易策略" tabindex="-1">② 交易策略 <a class="header-anchor" href="#_2-交易策略" aria-label="Permalink to &quot;② 交易策略&quot;">​</a></h3><ul><li>勾选 <strong>显示示例策略</strong> 可显示/隐藏平台自带的示例策略；</li><li><strong>绑定策略</strong> 下拉选择策略（创建后不可改）；</li><li>选中策略后会<strong>动态渲染该策略的可调参数</strong>：下拉类参数渲染为选择器，其余渲染为输入框（带单位）。</li></ul><h3 id="_3-账户与合约" tabindex="-1">③ 账户与合约 <a class="header-anchor" href="#_3-账户与合约" aria-label="Permalink to &quot;③ 账户与合约&quot;">​</a></h3><ul><li><strong>绑定账户</strong>：多选，列出全部交易网关 —— 一个模组可同时驱动多个账户（详见 <a href="/features/multi-account">多账户交易</a>）；</li><li><strong>绑定合约</strong>：远程搜索多选，可选项来自所选账户已订阅的合约。</li></ul><h3 id="_4-已关联合约" tabindex="-1">④ 已关联合约 <a class="header-anchor" href="#_4-已关联合约" aria-label="Permalink to &quot;④ 已关联合约&quot;">​</a></h3><p>只读表格，展示合约名称与用于交易算法的合约编码（可选中复制）。</p><p>底部按钮：<strong>取消 / 保存 / 保存并继续</strong>（新建时保存后清空名称，方便连续创建多个模组）。</p><h2 id="模组运行时" tabindex="-1">模组运行时 <a class="header-anchor" href="#模组运行时" aria-label="Permalink to &quot;模组运行时&quot;">​</a></h2><p>在模组管理页点 <strong>运行时状态</strong>，进入模组监控详情页：</p><ul><li><strong>K线图表区</strong>：可切换周期（1m ~ 1wk），主图 + 最多 5 个副图窗格；支持增加/移除/清空指标、显示（隐藏）历史持仓线、下载图表数据（CSV）、自动刷新开关；</li><li><strong>实时状态 / 历史表现</strong> 两个标签页；</li><li><strong>模组信息</strong>：当前余额、可用金额、占用金额、初始金额、总盈亏、总平仓盈亏、未平仓盈亏、总手续费、交易笔数、胜率、盈亏比、年化收益率、最大回撤、最大回撤率；</li><li><strong>手工调仓</strong>：开多 / 开空 / 平空 / 平多 + 提交 —— 直接干预模组持仓，用于应急处理；</li><li><strong>模组持仓</strong>、<strong>模组交易历史</strong>、<strong>模组绩效</strong> 图表。</li></ul><div class="tip custom-block"><p class="custom-block-title">回测模组也在这里看</p><p>用途为&quot;回测&quot;的模组在 <a href="/features/playback">历史回放</a> 运行时，同样通过本页实时观察策略在历史行情上的表现；&quot;历史表现&quot;页展示完整回测绩效。</p></div><h2 id="策略从哪来" tabindex="-1">策略从哪来 <a class="header-anchor" href="#策略从哪来" aria-label="Permalink to &quot;策略从哪来&quot;">​</a></h2><p>平台中的策略是实现了策略接口的 Java 类，有两种来源：</p><ol><li><strong>内置示例策略</strong>：平台自带约 11 个示例策略（名称含&quot;示例&quot;，模组表单默认隐藏，勾选&quot;显示示例策略&quot;可见），供学习参考；</li><li><strong>自研策略 jar 动态加载</strong>：把编译好的策略 jar 放到程序 jar 的<strong>同级目录</strong>，重启平台即被自动扫描注册，出现在&quot;绑定策略&quot;下拉中。</li></ol><div class="info custom-block"><p class="custom-block-title">策略开发</p><p>策略开发属于开发话题：继承 <code>AbstractStrategy</code>、标注 <code>@StrategicComponent(&quot;策略名&quot;)</code>、可选定义 <code>InitParams</code> 内部类暴露可调参数。仓库中的 <code>northstar-strategy-example</code> 模块提供了完整示例，也可使用平台内置的 AI 助手（策略编写助手）辅助编写。</p></div><h2 id="策略探索-批量回测" tabindex="-1">策略探索（批量回测） <a class="header-anchor" href="#策略探索-批量回测" aria-label="Permalink to &quot;策略探索（批量回测）&quot;">​</a></h2><p><strong>交易自动化 → 策略探索</strong> 用于批量验证策略：一个任务 = 一个策略 × 一组合约 × 一段历史区间，跑完直接出<strong>回测报告</strong>，适合参数寻优与品种筛选。</p><h3 id="新建任务" tabindex="-1">新建任务 <a class="header-anchor" href="#新建任务" aria-label="Permalink to &quot;新建任务&quot;">​</a></h3><p>点击新建，弹窗三页签：</p><ol><li><strong>任务信息</strong>：任务名称（≤16 字符）、预热起始日（默认 18 个月前）、测试开始日（默认 12 个月前）、测试结束日（默认今天）、分配金额（默认 20000；<em>回测交易量按分配金额的一半计算</em>）；</li><li><strong>交易策略</strong>：选择策略并填写参数（同模组表单）；</li><li><strong>测试合约</strong>：多选要测试的合约。</li></ol><h3 id="运行与报告" tabindex="-1">运行与报告 <a class="header-anchor" href="#运行与报告" aria-label="Permalink to &quot;运行与报告&quot;">​</a></h3><ul><li>任务列表每 5 秒自动刷新，显示进度条；</li><li>行操作：<strong>详情</strong>（查看设置）、<strong>回测</strong>（启动回测，进行中禁用）、<strong>移除</strong>、<strong>回测报告</strong>；</li><li><strong>回测报告</strong> 表格按合约逐行列出：交易合约、交易量、当前余额、交易笔数、总手续费、未平仓盈亏、总平仓盈亏、年化收益率%（可排序）、盈亏比（可排序）、胜率%（可排序）、最大回撤；</li><li>每行可打开 <strong>交易详情</strong>：盈亏分布、交易笔数、盈亏合计统计，记录过多时可下载。</li></ul><h2 id="模组状态速查" tabindex="-1">模组状态速查 <a class="header-anchor" href="#模组状态速查" aria-label="Permalink to &quot;模组状态速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状态</th><th>含义</th></tr></thead><tbody><tr><td>无持仓</td><td>空闲，等待信号</td></tr><tr><td>多头持仓 / 空头持仓</td><td>持有单向仓位</td></tr><tr><td>对冲锁仓 / 对冲持仓</td><td>双向持仓（锁仓）</td></tr><tr><td>等待中</td><td>已下单，等待订单反馈</td></tr><tr><td>异常</td><td>运行出错，请查看模组日志排查</td></tr></tbody></table><h2 id="策略上线推荐流程" tabindex="-1">策略上线推荐流程 <a class="header-anchor" href="#策略上线推荐流程" aria-label="Permalink to &quot;策略上线推荐流程&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>策略探索批量回测 → 创建&quot;回测&quot;模组精细验证 → 创建&quot;模拟盘&quot;模组试运行 → 创建&quot;实盘&quot;模组上线</span></span></code></pre></div>',37)])])}const p=r(e,[["render",s]]);export{c as __pageData,p as default};
